-- ----------------------------
-- Records of sys_dict
-- ----------------------------
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for sys_dict
-- ----------------------------
DROP TABLE IF EXISTS `sys_dict`;
CREATE TABLE `sys_dict`  (
 `id` int NOT NULL AUTO_INCREMENT,
 `name` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '参数key',
 `type` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '字典类型	',
 `code` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '字典编码	',
 `value` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '字典值	',
 `i18n` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '国际化code',
 `sort` int NOT NULL DEFAULT 0 COMMENT '排序',
 `uby` int NOT NULL COMMENT '更新人',
 `utime` datetime NOT NULL COMMENT '更新时间',
 `state` tinyint NOT NULL DEFAULT 1 COMMENT '默认：1   0：隐藏 1：显示',
 `build_in` tinyint NOT NULL DEFAULT 0 COMMENT '默认：0  0：非内置 1：内置',
 `remark` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
 PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 24 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sys_dict
-- ----------------------------

SET FOREIGN_KEY_CHECKS = 1;
